// Title: C# unit test that verifies a specific cell value is present in the HTML generated by Aspose.Cells
// Common Searches: C# unit test to confirm cell B2 value appears in Aspose.Cells HTML export | how to assert workbook.Save with SaveFormat.Html contains expected text using Aspose.Cells | verify Excel cell content in generated HTML with Aspose.Cells C# example | Aspose.Cells HTML output testing for specific cell value validation
// Tags: Aspose.Cells SaveFormat.Html cell verification | C# unit test Aspose.Cells HTML output | validate Excel to HTML conversion Aspose.Cells | assert cell value in generated HTML Aspose | memory stream HTML export Aspose.Cells test

using System;
using System.IO;
using System.Text;
using Aspose.Cells;

namespace AsposeCellsHtmlExportDemo
{
    // The example creates a workbook, writes "HelloWorld" to cell B2, saves the workbook to HTML in a MemoryStream, reads the HTML as a UTF‑8 string, and uses a simple assertion to confirm that the expected cell value is present in the generated HTML output.
    public class Program
    {
        public static void Main()
        {
            try
            {
                // Create a new workbook
                var workbook = new Workbook();

                // Access the first worksheet
                var sheet = workbook.Worksheets[0];

                // Set a specific cell value
                const string expectedValue = "HelloWorld";
                sheet.Cells["B2"].PutValue(expectedValue);

                // Save the workbook to HTML in a memory stream
                using (var ms = new MemoryStream())
                {
                    workbook.Save(ms, SaveFormat.Html);
                    ms.Position = 0;

                    // Read the HTML content as a string
                    string html;
                    using (var reader = new StreamReader(ms, Encoding.UTF8))
                    {
                        html = reader.ReadToEnd();
                    }

                    // Verify that the expected cell value appears in the HTML output
                    if (html.Contains(expectedValue))
                    {
                        Console.WriteLine("Test passed: HTML output contains the expected value.");
                    }
                    else
                    {
                        Console.WriteLine($"Test failed: HTML output does not contain expected value '{expectedValue}'.");
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"An error occurred: {ex.Message}");
            }
        }
    }
}
